class Solution:
    def maxDivScore(self, nums: List[int], divisors: List[int]) -> int:
        best, bestD = -1, 10**18
        for d in divisors:
            cnt = sum(1 for x in nums if x % d == 0)
            if cnt > best or (cnt == best and d < bestD):
                best, bestD = cnt, d
        return bestD

c.cpp:
class Solution {
public:
    int maxDivScore(vector<int>& nums, vector<int>& divisors) {
        int best = -1, bestD = INT_MAX;
        for (int d : divisors) {
            int cnt = 0;
            for (int x : nums) if (x % d == 0) cnt++;
            if (cnt > best || (cnt == best && d < bestD)) { best = cnt; bestD = d; }
        }
        return bestD;
    }
};

