var maxDivScore = function(nums, divisors) {
    let best = -1, bestD = Infinity;
    for (const d of divisors) {
        let cnt = 0;
        for (const x of nums) if (x % d === 0) cnt++;
        if (cnt > best || (cnt === best && d < bestD)) { best = cnt; bestD = d; }
